# The two player bodies: chunky, faceted low-poly dwarves (decision 0288), hand-built in Blender
# through the Blender MCP. Nothing here is generated by an AI tool or taken from another model.
#
#     import sys; sys.path.insert(0, r'<repo>/tools/art')
#     import heroic_dwarves as hd
#     hd.REPO = r'<repo>'
#     made = hd.build(hd.MAN)            # or hd.WOMAN: the body, its hair and its beards, rigged
#     hd.render_views(made, out_dir)     # preview pictures, arms relaxed
#     hd.export_body(made, tmp_dir)      # assets/characters/knight.glb (the man) or barbarian.glb
#
# The shapes are heroic rather than cute: a broad barrel chest, heavy shoulders, thick forearms,
# big hands and bare feet, a strong face under a heavy brow. Everything is flat-shaded, so every
# facet shows, and coloured per facet with no texture. They wear the plain clothes every character
# starts in (decision 0112): a rough shirt and shorts, bare feet.
#
# Both stand on the soft dwarves' skeleton exactly as it was (decision 0272), so every move, seat,
# bed and reach in the game still fits. The skeleton is taken from the body file already in the
# repo. Facing -Y, Z up, the left hand at +X, arms out in a T.
#
# Three materials: cloth (clothes, eyes, mouth), skin (marked 'skin', which the game shades for the
# player's skin tone) and hair (marked 'hair': hair, brows and beards, so a hair colour can be
# chosen later). The body is one object, `dwarf1` or `dwarf2`. Hair is `<id>_Hair` and each beard
# `<id>_Beard_<style>`, so the game can show one beard and, later, hide hair under a helm.
import math
import os

