# ---------------------------------------------------------------- small helpers

def hexc(h):
    h = h.lstrip('#')
    return tuple((int(h[i:i + 2], 16) / 255) ** 2.2 for i in (0, 2, 4))  # stored linear, as glTF expects


def mix(a, b, t):
    t = max(0.0, min(1.0, t))
    return tuple(a[i] + (b[i] - a[i]) * t for i in range(3))


def rnd(a, b=0.0, c=0.0):
    """A repeatable number from 0 to 1."""
    v = math.sin(a * 12.9898 + b * 78.233 + c * 37.719 + 1.37) * 43758.5453
    return v - math.floor(v)


def smooth(a, b, t):
    t = max(0.0, min(1.0, (t - a) / (b - a)))
    return t * t * (3 - 2 * t)


def mx(p):
    return Vector((-p[0], p[1], p[2]))


def ring(c, u, v, n, p=2.0, phase=0.0, v_neg=None):
    """A squarish loop of n points round c. u and v are its half-axes; v_neg, if given, is how far
    it reaches the other way along v (a belly that sticks out further in front than behind)."""
    c, u, v = Vector(c), Vector(u), Vector(v)
    pts = []
    for k in range(n):
        a = math.tau * k / n + phase
        ca, sa = math.cos(a), math.sin(a)
        x = math.copysign(abs(ca) ** (2 / p), ca)
        y = math.copysign(abs(sa) ** (2 / p), sa)
        vv = v if (y >= 0 or v_neg is None) else v.normalized() * v_neg
        pts.append(c + u * x + vv * y)
    return pts


def loft(rings, cap_start=True, cap_end=True):
    """A skin stretched over a row of loops, all with the same number of points."""
    bm = bmesh.new()
    rows = [[bm.verts.new(p) for p in r] for r in rings]
    n = len(rows[0])
    for a, b in zip(rows, rows[1:]):
        for k in range(n):
            bm.faces.new((a[k], a[(k + 1) % n], b[(k + 1) % n], b[k]))
    if cap_start:
        bm.faces.new(list(reversed(rows[0])))
    if cap_end:
        bm.faces.new(rows[-1])
    return bm


def hull(points):
    """The faceted lump that wraps a handful of points."""
    bm = bmesh.new()
    seen = []
    for p in points:
        p = Vector(p)
        if all((p - q).length > 1e-5 for q in seen):
            seen.append(p)
            bm.verts.new(p)
    out = bmesh.ops.convex_hull(bm, input=bm.verts)
    for v in out.get('geom_interior', []) + out.get('geom_unused', []):
        if isinstance(v, bmesh.types.BMVert) and v.is_valid:
            bm.verts.remove(v)
    return bm


def sym(points):
    """Points plus their mirror images, for a lump that straddles the middle."""
    return [Vector(p) for p in points] + [mx(p) for p in points if abs(p[0]) > 1e-6]


def lump(c, r, squash=(1, 1, 1), turn=0.0, detail=1, seed=0.0, rough=.0):
    """A rough faceted ball."""
    bm = bmesh.new()
    bmesh.ops.create_icosphere(bm, subdivisions=detail, radius=1.0)
    rot = Matrix.Rotation(turn, 3, 'Z')
    for i, v in enumerate(bm.verts):
        k = 1 + (rnd(i, seed) - .5) * rough
        co = Vector((v.co.x * squash[0], v.co.y * squash[1], v.co.z * squash[2])) * r * k
        v.co = Vector(c) + rot @ co
    return bm


def mirrored(bm):
    out = bm.copy()
    for v in out.verts:
        v.co.x = -v.co.x
    bmesh.ops.reverse_faces(out, faces=out.faces)
    return out


class Sculpt:
    """Gathers lumps into one object, giving every facet its colour and every point its bones."""

    def __init__(self, name):
        self.name = name
        self.bm = bmesh.new()
        self.col = self.bm.loops.layers.float_color.new('Col')
        self.bones = {}
        self.count = 0

    def add(self, piece, colour, mat, bones, vary=.07, both=False):
        """colour: a hex, or a function of a facet's middle and normal giving a linear colour.
        bones: the bones that may move these points, or a function of a point giving its weights."""
        for copy_index, src in enumerate((piece, mirrored(piece)) if both else (piece,)):
            bmesh.ops.recalc_face_normals(src, faces=src.faces)
            src.normal_update()
            spec = bones
            if both and copy_index == 1 and not callable(bones):
                spec = [flip_name(b) for b in bones]
            made = {}
            for v in src.verts:
                nv = self.bm.verts.new(v.co)
                made[v] = nv
                self.bones[nv] = (spec, copy_index == 1 and callable(bones))
            for f in src.faces:
                nf = self.bm.faces.new([made[v] for v in f.verts])
                nf.material_index = mat
                centre = f.calc_center_median()
                if callable(colour):
                    c = colour(Vector((abs(centre.x), centre.y, centre.z)), f.normal)
                else:
                    c = hexc(colour)
                self.count += 1
                k = 1 + (rnd(self.count, len(self.name)) - .5) * vary
                # Facets that face the ground are a touch darker, as if lit from above.
                k *= .95 + .05 * smooth(-1, .3, f.normal.z)
                for loop in nf.loops:
                    loop[self.col] = (c[0] * k, c[1] * k, c[2] * k, 1.0)
            if src is not piece:
                src.free()
        piece.free()

    def finish(self, collection, materials, rig):
        me = bpy.data.meshes.new(self.name)
        ob = bpy.data.objects.new(self.name, me)
        collection.objects.link(ob)
        segs = {}
        for base, (h, t) in BONES.items():
            for side in ((1, -1) if base in SIDED else (1,)):
                name = base + ('.l' if side > 0 else '.r') if base in SIDED else base
                segs[name] = (Vector(h), Vector(t)) if side > 0 else (mx(h), mx(t))
        weights = []
        self.bm.verts.ensure_lookup_table()
        for v in self.bm.verts:
            spec, flipped = self.bones[v]
            if callable(spec):
                w = spec(Vector((-v.co.x, v.co.y, v.co.z)) if flipped else v.co)
                if flipped:
                    w = {flip_name(k): x for k, x in w.items()}
            else:
                near = sorted((dist_to_segment(v.co, *segs[n]), n) for n in spec)[:2]
                raw = [(1 / (d + .012) ** 4, n) for d, n in near]
                total = sum(x for x, _ in raw)
                w = {n: x / total for x, n in raw}
            weights.append(w)
        self.bm.to_mesh(me)
        self.bm.free()
        for p in me.polygons:
            p.use_smooth = False
        me.color_attributes.active_color = me.color_attributes['Col']
        me.color_attributes.render_color_index = me.color_attributes.find('Col')
        for m in materials:
            me.materials.append(m)
        groups = {}
        for i, w in enumerate(weights):
            for name, x in w.items():
                if x < .01:
                    continue
                g = groups.get(name) or ob.vertex_groups.new(name=name)
                groups[name] = g
                g.add([i], x, 'REPLACE')
        ob.parent = rig
        ob.modifiers.new('Armature', 'ARMATURE').object = rig
        return ob


def flip_name(name):
    return name[:-2] + ('.r' if name.endswith('.l') else '.l') if name[-2:] in ('.l', '.r') else name


def dist_to_segment(p, a, b):
    ab = b - a
    t = 0 if ab.length_squared == 0 else max(0, min(1, (p - a).dot(ab) / ab.length_squared))
    return (p - (a + ab * t)).length


def tree_of(bm):
    copy = bm.copy()
    bmesh.ops.triangulate(copy, faces=copy.faces)
    return BVHTree.FromBMesh(copy)


def front_of(tree, x, z, fallback=-.1):
    """How far forward (-Y) a shape reaches at this spot."""
    hit = tree.ray_cast(Vector((x, -2, z)), Vector((0, 1, 0)))
    return hit[0].y if hit[0] is not None else fallback


def patch(tree, outline, lift):
    """A flat piece laid on a surface, a little proud of it: eyes, lips."""
    bm = bmesh.new()
    verts = [bm.verts.new((x, front_of(tree, x, z) - lift, z)) for x, z in outline]
    bm.faces.new(verts)
    return bm


def oval(cx, cz, rx, rz, n=8, tilt=0.0):
    c, s = math.cos(tilt), math.sin(tilt)
    out = []
    for k in range(n):
        a = math.tau * k / n
        x, z = rx * math.cos(a), rz * math.sin(a)
        out.append((cx + x * c - z * s, cz + x * s + z * c))
    return out


# ---------------------------------------------------------------- the body

def torso_rings(B):
    return [ring((0, 0, z), (rx, 0, 0), (0, rb, 0), 12, p, v_neg=rf) for z, rx, rf, rb, p in B['torso']]


def torso_colour(B):
    shirt, shade = hexc(B['shirt']), hexc(B['shirt_shade'])
    shorts, rope, skin = hexc(B['shorts']), hexc(B['rope']), hexc(B['skin'])

    def colour(c, n):
        if c.z < .40:
            return shorts
        if c.z > .91:
            return skin
        # A V at the throat shows the chest.
        if c.y < 0 and c.z > .80 and c.x < (c.z - .80) * .75:
            return skin
        return mix(shirt, shade, smooth(.5, -.6, n.z))
    return colour


def body_pieces(S, B):
    skin, shade = hexc(B['skin']), hexc(B['skin_shade'])
    shirt, shirt_shade = hexc(B['shirt']), hexc(B['shirt_shade'])
    core = ['hips', 'spine', 'chest']

    torso = loft(torso_rings(B))
    tree = tree_of(torso)
    S.add(torso, torso_colour(B), CLOTH, core, vary=.06)

    # The shirt's hem flares over the shorts, and a rope holds the shorts up beneath it.
    z0, rx, rf, rb, p = B['torso'][2]
    hem = loft([
        ring((0, 0, z0 - .035), (rx + .022, 0, 0), (0, rb + .02, 0), 12, p, v_neg=rf + .022),
        ring((0, 0, z0 + .03), (rx + .004, 0, 0), (0, rb + .004, 0), 12, p, v_neg=rf + .004),
    ])
    S.add(hem, lambda c, n: mix(shirt, shirt_shade, .5 if n.z < -.3 else 0), CLOTH, core, vary=.05)

    # Collar: a raised band round the neck, open at the front.
    zc = .915
    for side in (1, -1):
        pts = []
        for a in (20, 60, 100, 140, 178):
            r = math.radians(a)
            x, y = math.sin(r) * .125 * side, -math.cos(r) * .105
            pts += [(x, y, zc - .02), (x * 1.13, y * 1.13 - .004, zc - .03), (x * 1.04, y * 1.04, zc + .028)]
        S.add(hull(pts), B['shirt_shade'], CLOTH, ['chest'], vary=.05)
    # Lacing across the V.
    for i, z in enumerate((.835, .87)):
        w = (z - .80) * .62
        for s in (1, -1):
            y0, y1 = front_of(tree, -w * s, z - .014) - .006, front_of(tree, w * s, z + .014) - .006
            a, b = Vector((-w * s, y0, z - .014)), Vector((w * s, y1, z + .014))
            S.add(hull([a + Vector((0, 0, .006)), a - Vector((0, 0, .006)), b + Vector((0, 0, .006)),
                        b - Vector((0, 0, .006)), a + Vector((0, -.006, 0)), b + Vector((0, -.006, 0))]),
                  B['lace'], CLOTH, ['chest'], vary=.03)

    nx, ny = B['neck']
    neck = loft([ring((0, .004, .91), (nx + .02, 0, 0), (0, ny + .02, 0), 10, 2.2),
                 ring((0, 0, .96), (nx, 0, 0), (0, ny, 0), 10, 2.2),
                 ring((0, -.004, 1.0), (nx - .006, 0, 0), (0, ny - .004, 0), 10, 2.2)])
    S.add(neck, lambda c, n: mix(skin, shade, .6), SKIN, ['chest', 'head'], vary=.04)

    arm_pieces(S, B)
    leg_pieces(S, B)
    return tree


def arm_pieces(S, B):
    skin, shade = hexc(B['skin']), hexc(B['skin_shade'])
    shirt, shirt_shade = hexc(B['shirt']), hexc(B['shirt_shade'])
    sz, sy = B['shoulder']
    y, z = .072, .86

    def loop(x, r, n=8, flat=1.0, dy=0.0, dz=0.0, p=2.3):
        return ring((x, y + dy, z + dz), (0, r * flat, 0), (0, 0, r), n, p, phase=math.pi / 8)

    # The sleeve: a heavy shoulder, ending in a loose cuff above the elbow.
    sleeve = loft([
        loop(.17, sz * .8, dz=-.01), loop(.235, sz, flat=sy / sz, dz=.004), loop(.30, sz * .97, flat=sy / sz),
        loop(.355, B['upper_arm'] + .022), loop(.375, B['upper_arm'] + .026),
    ])
    S.add(sleeve, lambda c, n: mix(shirt, shirt_shade, smooth(.3, -.7, n.z) * .8 + (.5 if c.x > .36 else 0)),
          CLOTH, ['chest', 'upperarm.l'], both=True, vary=.06)

    arm = loft([
        loop(.34, B['upper_arm'] * .96), loop(.39, B['upper_arm']), loop(.45, B['elbow'], dz=-.004),
        loop(.50, B['forearm'], dz=-.004), loop(.545, B['forearm'] * .86), loop(.585, B['wrist'], flat=1.12),
        loop(.60, B['wrist'] * .97, flat=1.12),
    ])
    S.add(arm, lambda c, n: mix(skin, shade, smooth(.2, -.8, n.z) * .7), SKIN,
          ['upperarm.l', 'lowerarm.l', 'hand.l'], both=True, vary=.06)

    # A big square hand, palm down, fingers curled a little, the thumb forward.
    h = B['hand']
    o = Vector((.595, .075, .845))

    def at(dx, dy, dz):
        return o + Vector((dx, dy, dz)) * h

    palm = hull([at(0, s * .046, t) for s in (1, -1) for t in (.036, -.034)]
                + [at(.08, s * .064, t) for s in (1, -1) for t in (.03, -.034)]
                + [at(.04, s * .066, .04) for s in (1, -1)] + [at(.04, 0, .046)])
    fingers = hull([at(.074, s * .062, t) for s in (1, -1) for t in (.03, -.03)]
                   + [at(.125, s * .058, t) for s in (1, -1) for t in (.014, -.044)]
                   + [at(.152, s * .05, t) for s in (1, -1) for t in (-.024, -.066)])
    thumb = hull([at(.01, -.034, t) for t in (.022, -.026)] + [at(.05, -.046, t) for t in (.02, -.03)]
                 + [at(.052, -.096, t) for t in (.004, -.036)] + [at(.092, -.112, t) for t in (-.012, -.05)]
                 + [at(.092, -.078, -.04)])
    hand_skin = lambda c, n: mix(skin, shade, smooth(.2, -.8, n.z) * .8)
    for piece in (palm, fingers, thumb):
        S.add(piece, hand_skin, SKIN, ['hand.l'], both=True, vary=.07)
    # Knuckle lines.
    for i in (-1, 0, 1):
        yk = i * .034
        S.add(hull([at(.08, yk - .003, .031), at(.08, yk + .003, .031), at(.122, yk - .003, .017),
                    at(.122, yk + .003, .017), at(.1, yk, .021)]),
              B['skin_shade'], SKIN, ['hand.l'], both=True, vary=.02)


def leg_pieces(S, B):
    skin, shade = hexc(B['skin']), hexc(B['skin_shade'])
    shorts, shorts_shade = hexc(B['shorts']), hexc(B['shorts_shade'])
    x = .14

    def loop(z, r, dy=0.0, dx=0.0, n=8, flat=1.0):
        return ring((x + dx, .015 + dy, z), (r, 0, 0), (0, r * flat, 0), n, 2.3, phase=math.pi / 8)

    t = B['thigh']
    trouser = loft([loop(.40, t * .92, dx=-.02), loop(.33, t, dx=-.006), loop(.265, t * .98), loop(.235, t * 1.03)])
    S.add(trouser, lambda c, n: mix(shorts, shorts_shade, .6 if c.z < .25 else smooth(.3, -.6, n.z) * .5),
          CLOTH, ['hips', 'upperleg.l', 'lowerleg.l'], both=True, vary=.06)
    leg = loft([loop(.26, t * .84), loop(.215, B['knee'], dy=-.008), loop(.165, B['calf'], dy=.012),
                loop(.115, B['calf'] * .86, dy=.008), loop(.075, B['ankle'], dy=.004), loop(.045, B['ankle'] * 1.02)])
    S.add(leg, lambda c, n: mix(skin, shade, smooth(.2, -.8, n.z) * .6), SKIN,
          ['upperleg.l', 'lowerleg.l', 'foot.l'], both=True, vary=.06)

    f = B['foot']

    def at(dx, y, z):
        return Vector((x + dx * f, .02 + (y - .02) * f, z * f))

    foot = hull([at(s * .046, .092, 0) for s in (1, -1)] + [at(s * .04, .088, .07) for s in (1, -1)]
                + [at(s * .05, .03, .085) for s in (1, -1)]
                + [at(-.066, -.10, 0), at(.07, -.09, 0), at(-.058, -.10, .058), at(.06, -.09, .05)]
                + [at(-.07, -.165, 0), at(.066, -.14, 0), at(-.052, -.15, .046), at(.05, -.13, .04)])
    foot_skin = lambda c, n: mix(skin, shade, smooth(.3, -.8, n.z) * .8)
    S.add(foot, foot_skin, SKIN, ['foot.l', 'toes.l'], both=True, vary=.06)
    # Toes: a big one and three smaller, stepping back towards the outside.
    toes = ((-.046, .024, -.205, .042), (-.012, .017, -.192, .034), (.018, .016, -.176, .03), (.046, .016, -.158, .028))
    for cx, w, tip, hgt in toes:
        S.add(hull([at(cx + s * w, -.13, t) for s in (1, -1) for t in (0, hgt)]
                   + [at(cx + s * w * .9, tip + .012, t) for s in (1, -1) for t in (0, hgt * .9)]
                   + [at(cx, tip, hgt * .45), at(cx, tip + .004, 0)]),
              foot_skin, SKIN, ['toes.l'], both=True, vary=.07)


# ---------------------------------------------------------------- the head

HEAD_FOOT = .955  # the head grows from here, so its size can change without lifting it off the neck


def head_loops(B):
    """The head's loops at this body's head size: (height, side, front, back, centre, squareness)."""
    k = B.get('head_size', 1.0)
    return [(HEAD_FOOT + (z - HEAD_FOOT) * k, rx * k, rf * k, rb * k, cy * k, p) for z, rx, rf, rb, cy, p in B['head']]


def head_rings(B, grow=0.0):
    out = []
    for z, rx, rf, rb, cy, p in head_loops(B):
        out.append(ring((0, cy, z), (rx + grow, 0, 0), (0, rb + grow, 0), 12, p, v_neg=rf + grow))
    return out


def head_pieces(S, B):
    woman = B['id'] == 'dwarf2'
    skin, shade, blush = hexc(B['skin']), hexc(B['skin_shade']), hexc(B['blush'])
    head = loft(head_rings(B))
    tree = tree_of(head)

    def face_colour(c, n):
        col = mix(skin, shade, smooth(.1, -.8, n.z) * .7)
        cheek = (Vector((c.x, c.z)) - Vector((.088, 1.068))).length
        if c.y < -.03:
            col = mix(col, blush, (1 - smooth(.015, .06, cheek)) * .55)
        return col
    S.add(head, face_colour, SKIN, ['head'], vary=.05)

    def on_face(x, z, out=0.0):
        return Vector((x, front_of(tree, x, z) - out, z))

    # Ears.
    S.add(hull([(.124, .0, 1.085), (.128, .035, 1.10), (.162, .03, 1.098), (.176, .04, 1.135), (.168, .035, 1.168),
                (.13, .0, 1.172), (.126, .04, 1.15), (.15, .008, 1.13)]),
          lambda c, n: mix(skin, blush, .25), SKIN, ['head'], both=True, vary=.08)

    if woman:
        nose = hull(sym([(.01, 0, 1.124), (.018, 0, 1.098), (.026, 0, 1.08), (.015, -.026, 1.088), (.0, -.032, 1.093),
                         (.0, -.012, 1.072), (.0, 0, 1.128)]))
    else:
        nose = hull(sym([(.016, 0, 1.16), (.026, -.018, 1.13), (.036, -.066, 1.094), (.0, -.084, 1.1),
                         (.054, -.02, 1.076), (.036, 0, 1.066), (.0, -.04, 1.06), (.0, -.004, 1.164),
                         (.04, 0, 1.10), (.0, -.064, 1.122)]))
    base_y = front_of(tree, 0, 1.10) + .012
    for v in nose.verts:
        v.co.y += base_y
    S.add(nose, lambda c, n: mix(skin, blush, .35 + .3 * smooth(1.13, 1.08, c.z)), SKIN, ['head'], vary=.08)

    # Brow ridge and eyebrows.
    if woman:
        brow = [(.022, 1.158, .010, .006), (.06, 1.169, .012, .009), (.1, 1.16, .009, .004)]
    else:
        brow = [(.014, 1.152, .016, .014), (.058, 1.172, .019, .02), (.112, 1.166, .013, .01)]
    pts = []
    for bx, bz, half, out in brow:
        pts += [on_face(bx, bz - half, out), on_face(bx, bz + half, out * .7), on_face(bx, bz, -.01)]
    S.add(hull(pts), lambda c, n: hexc(B['hair_dark']), HAIR, ['head'], both=True, vary=.08)

    # Eyes: a white, a dark iris and a bright glint, under a shaded lid.
    ex, ez = (.056, 1.126) if woman else (.057, 1.127)
    rx, rz = (.024, .0175) if woman else (.022, .0135)
    S.add(patch(tree, oval(ex, ez, rx * 1.22, rz * 1.4, 10), .0015), B['skin_shade'], SKIN, ['head'], both=True,
          vary=.02)
    S.add(patch(tree, oval(ex, ez, rx, rz, 10), .003), B['eye'], CLOTH, ['head'], both=True, vary=.0)
    S.add(patch(tree, oval(ex - .003, ez - .001, rz * .86, rz * .92, 8), .0045), B['iris'], CLOTH, ['head'],
          both=True, vary=.0)
    S.add(patch(tree, oval(ex + .003, ez + .005, .0036, .0036, 4), .006), '#ffffff', CLOTH, ['head'], both=True,
          vary=.0)
    # The upper lid: a dark line, with lashes sweeping out for the woman.
    low = .78 if woman else .5  # how far down over the eye the lid comes
    lid = [(ex - rx * 1.05, ez + rz * .15), (ex - rx * .5, ez + rz * low), (ex + rx * .5, ez + rz * (low + .04)),
           (ex + rx * 1.08, ez + rz * .2), (ex + rx * (1.45 if woman else 1.1), ez + rz * (.9 if woman else .5)),
           (ex + rx * .5, ez + rz * 1.45), (ex - rx * .5, ez + rz * 1.4)]
    S.add(patch(tree, lid, .0055), B['iris'] if woman else B['hair_dark'], CLOTH, ['head'], both=True, vary=.0)

    # Mouth.
    mz = 1.034 if woman else 1.038
    mw = .034 if woman else .044
    up, gap = (.007, .004) if woman else (.004, .009)  # how far the corners lift, and how far it opens
    S.add(patch(tree, [(-mw, mz + up), (-mw * .5, mz + .001), (0, mz), (mw * .5, mz + .001), (mw, mz + up),
                       (mw * .5, mz - gap * .8), (0, mz - gap), (-mw * .5, mz - gap * .8)], .003),
          B['mouth'], CLOTH, ['head'], vary=.0)
    lip_y = lambda x, z: front_of(tree, x, z)
    lower = hull([(s * mw * .62, lip_y(mw * .62, mz - .012) - .002, mz - .01) for s in (1, -1)]
                 + [(s * mw * .3, lip_y(0, mz - .02) - .012, mz - .017) for s in (1, -1)]
                 + [(0, lip_y(0, mz - .03) - .004, mz - .03), (0, lip_y(0, mz - .012) - .007, mz - .009),
                    (0, lip_y(0, mz - .02) + .01, mz - .02)])
    S.add(lower, B['lip'], CLOTH if woman else SKIN, ['head'], vary=.04)
    if woman:
        upper = hull([(s * mw * .7, lip_y(mw * .7, mz + .006) - .002, mz + .005) for s in (1, -1)]
                     + [(s * mw * .25, lip_y(0, mz + .014) - .009, mz + .015) for s in (1, -1)]
                     + [(0, lip_y(0, mz + .01) - .008, mz + .009), (0, lip_y(0, mz + .01) + .01, mz + .008)])
        S.add(upper, B['lip'], CLOTH, ['head'], vary=.04)
    return tree


# ---------------------------------------------------------------- hair and beards

def hair_colour(B):
    base, dark, light = hexc(B['hair']), hexc(B['hair_dark']), hexc(B['hair_light'])

    def colour(c, n):
        return mix(mix(dark, base, smooth(-.6, .2, n.z)), light, smooth(.5, 1, n.z) * .6)
    return colour


def hairline_rings(B, line, grow=.014):
    """The head's own loops pushed out where there is hair and pulled in where there is none, so
    the skin of hair meets the scalp along the hairline. line(z) is how far round from the front,
    in degrees, the hair begins at that height."""
    out = []
    for z, rx, rf, rb, cy, p in head_loops(B):
        start = line(z)
        loop = []
        for k in range(12):
            a = math.tau * k / 12
            ca, sa = math.cos(a), math.sin(a)
            from_front = math.degrees(math.acos(max(-1, min(1, -sa))))
            g = grow if from_front >= start else -.03
            x = math.copysign(abs(ca) ** (2 / p), ca) * (rx + g)
            y = math.copysign(abs(sa) ** (2 / p), sa) * ((rb if sa >= 0 else rf) + g)
            loop.append(Vector((x, cy + y, z + (.006 if g > 0 and z > 1.2 else 0))))
        out.append(loop)
    return out


def chain(points, r, seed=0.0, squash=(1, 1, 1)):
    """A braid: a row of faceted knots, each turned a little from the last."""
    return [lump(p, r * (1 - .05 * i), squash, turn=i * .9 + seed, detail=1, seed=seed + i, rough=.16)
            for i, p in enumerate(points)]


def band(c, r, h=.014):
    """A gold ring round a braid."""
    return loft([ring((c[0], c[1], c[2] - h), (r, 0, 0), (0, r, 0), 6), ring((c[0], c[1], c[2] + h), (r, 0, 0), (0, r, 0), 6)])


def man_hair(B, rig, collection, materials):
    S = Sculpt(B['id'] + '_Hair')
    col = hair_colour(B)

    def line(z):
        # Short at the nape, behind the ears, back from the temples, and over the whole crown.
        return 200 if z < 1.02 else 128 if z < 1.11 else 104 if z < 1.15 else 76 if z < 1.2 else 40 if z < 1.24 else 0
    S.add(loft(hairline_rings(B, line)), col, HAIR, ['head'], vary=.1)
    # Swept back into a knot, bound in gold, with a short tail.
    S.add(lump((0, .105, 1.262), .058, (1, 1.05, .9), detail=1, seed=3, rough=.2), col, HAIR, ['head'], vary=.1)
    S.add(band((0, .112, 1.228), .034, .009), GOLD, CLOTH, ['head'], vary=.05)
    S.add(hull([(s * .03, .125, 1.22) for s in (1, -1)] + [(s * .04, .165, 1.17) for s in (1, -1)]
               + [(0, .11, 1.2), (0, .18, 1.2), (0, .155, 1.09), (.02, .14, 1.12), (-.02, .14, 1.12)]),
          col, HAIR, ['head'], vary=.1)
    return S.finish(collection, materials, rig)


def woman_hair(B, rig, collection, materials, chest_tree):
    S = Sculpt(B['id'] + '_Hair')
    col = hair_colour(B)

    def line(z):
        return (200 if z < .98 else 130 if z < 1.06 else 112 if z < 1.11 else 84 if z < 1.16 else 58 if z < 1.2
                else 30 if z < 1.24 else 0)
    S.add(loft(hairline_rings(B, line, grow=.018)), col, HAIR, ['head'], vary=.1)
    # A parted fringe sweeping down each temple.
    S.add(hull([(.004, -.118, 1.262), (.004, -.135, 1.215), (.06, -.132, 1.19), (.112, -.092, 1.15),
                (.142, -.03, 1.13), (.14, -.02, 1.22), (.09, -.09, 1.245), (.03, -.07, 1.285), (.1, -.02, 1.27)]),
          col, HAIR, ['head'], both=True, vary=.1)
    # A bun at the crown.
    S.add(lump((0, .07, 1.3), .07, (1.1, 1, .8), detail=1, seed=5, rough=.18), col, HAIR, ['head'], vary=.1)

    # Two thick braids from behind the ears, lying forward over the shoulders.
    def follows(co):
        w = smooth(.9, 1.0, co.z)
        return {'head': w, 'chest': 1 - w}
    zs = (1.05, .985, .925, .865, .805, .745, .69)
    pts = []
    for i, z in enumerate(zs):
        x = (.15, .17, .178, .165, .15, .14, .134)[i]
        y = (-.0, -.03, -.07, None, None, None, None)[i]
        if y is None:
            y = front_of(chest_tree, x, z) - .04
        pts.append((x, y, z))
    for i, knot in enumerate(chain(pts, .05, seed=2, squash=(1, 1, 1.05))):
        S.add(knot, col, HAIR, follows, both=True, vary=.12)
    end = pts[-1]
    S.add(band((end[0], end[1], end[2] - .04), .034), GOLD, CLOTH, follows, both=True, vary=.05)
    S.add(hull([(end[0] + dx, end[1] + dy, end[2] - .05) for dx in (-.026, .026) for dy in (-.026, .026)]
               + [(end[0], end[1] - .004, end[2] - .135)]), col, HAIR, follows, both=True, vary=.12)
    return S.finish(collection, materials, rig)


def moustache(B, face, droop=.0, size=1.0):
    """One side of a moustache: thick under the nose, sweeping out past the corner of the mouth."""
    y0 = front_of(face, 0, 1.06)
    pts = [(.0, y0 - .018 * size, 1.07), (.0, y0 - .022 * size, 1.05), (.0, y0 + .01, 1.062),
           (.03, y0 - .03 * size, 1.064), (.034, y0 - .026 * size, 1.038),
           (.07, y0 - .012, 1.05), (.075, y0 - .008, 1.022 - droop * .5),
           (.108, y0 + .024, 1.03 - droop * .6), (.118, y0 + .034, 1.0 - droop), (.06, y0 + .02, 1.045)]
    return hull(pts)


def beard_mass(face, chest, top, bottom, width, point=.0, depth=.05):
    """The body of a beard: from the cheeks down to its end, lying on the chest."""
    y_chin = front_of(face, 0, 1.0)
    y_end = min(front_of(chest, 0, max(bottom, .5)), y_chin + .02) - depth
    pts = [(.134, -.02, top + .03), (.142, .02, top + .02), (.128, -.075, top - .03), (.07, y_chin - .016, top - .055),
           (.0, y_chin - .026, top - .058),
           (width, y_chin + .02, 1.0), (width * .9, y_chin - .03, .97), (.0, y_chin - .055, .985),
           (width * .8, .0, .96), (.0, .02, .95)]
    mid = (bottom + .97) / 2
    pts += [(width * .85, y_end + .03, mid), (.0, y_end - .01, mid), (width * .5, y_end, mid - .02)]
    pts += [(width * (.5 - point * .4), y_end + .02, bottom + .03), (.0, y_end + .005, bottom),
            (width * .3, y_end + .05, bottom + .02)]
    return hull(sym(pts))


def beards(B, rig, collection, materials, face, chest):
    col = hair_colour(B)
    made = {}
    y_chin = front_of(face, 0, 1.0)

    def chops():
        return hull([(.128, -.03, 1.13), (.14, .02, 1.12), (.132, -.085, 1.06), (.142, -.02, 1.02), (.128, -.1, 1.0),
                     (.09, -.125, .985), (.11, -.05, .962), (.13, .02, 1.0), (.075, y_chin - .012, 1.03)])

    for style in BEARD_STYLES:
        S = Sculpt('%s_Beard_%s' % (B['id'], style))
        add = lambda piece, both=False: S.add(piece, col, HAIR, ['head'], both=both, vary=.12)
        if style == 'stache':
            add(moustache(B, face, droop=.07, size=1.5), True)
            add(hull(sym([(.022, y_chin - .012, 1.012), (.0, y_chin - .03, .985), (.0, y_chin - .008, .962),
                          (.0, y_chin + .01, 1.0)])))
        elif style == 'chops':
            add(moustache(B, face, droop=.03, size=1.2), True)
            add(chops(), True)
        elif style == 'full':
            add(moustache(B, face, droop=.02, size=1.2), True)
            add(beard_mass(face, chest, 1.09, .76, .15, depth=.06))
            add(lump((0, front_of(chest, 0, .86) - .05, .86), .085, (1.25, .7, 1.1), detail=1, seed=7, rough=.2))
        elif style == 'long':
            add(moustache(B, face, droop=.05, size=1.25), True)
            add(beard_mass(face, chest, 1.09, .66, .135, point=1, depth=.05))
            yb = front_of(chest, 0, .66) - .05
            S.add(band((0, yb + .012, .668), .04), GOLD, CLOTH, ['head'], vary=.05)
            add(hull([(s * .03, yb + dy, .655) for s in (1, -1) for dy in (-.02, .04)] + [(0, yb + .012, .575)]))
        else:  # braids
            add(moustache(B, face, droop=.05, size=1.3), True)
            add(beard_mass(face, chest, 1.09, .87, .145, depth=.055))
            pts = [(.072, front_of(chest, .072, z) - .05, z) for z in (.875, .815, .755, .7)]
            for knot in chain(pts, .05, seed=1):
                add(knot, True)
            end = pts[-1]
            S.add(band((end[0], end[1], end[2] - .042), .034), GOLD, CLOTH, ['head'], both=True, vary=.05)
            add(hull([(end[0] + dx, end[1] + dy, end[2] - .05) for dx in (-.026, .026) for dy in (-.026, .026)]
                     + [(end[0], end[1], end[2] - .13)]), True)
        made[style] = S.finish(collection, materials, rig)
    return made


# ---------------------------------------------------------------- putting one together

def material(name, kind):
    mat = bpy.data.materials.get(name) or bpy.data.materials.new(name)
    mat.use_nodes = True
    nt = mat.node_tree
    for n in list(nt.nodes):
        if n.type != 'OUTPUT_MATERIAL':
            nt.nodes.remove(n)
    out = [n for n in nt.nodes if n.type == 'OUTPUT_MATERIAL'][0]
    bsdf = nt.nodes.new('ShaderNodeBsdfPrincipled')
    # A different roughness each keeps the glTF import step from merging them into one material.
    bsdf.inputs['Roughness'].default_value = {CLOTH: .86, SKIN: .8, HAIR: .9}[kind]
    vc = nt.nodes.new('ShaderNodeVertexColor')
    vc.layer_name = 'Col'
    nt.links.new(vc.outputs['Color'], bsdf.inputs['Base Color'])
    nt.links.new(bsdf.outputs['BSDF'], out.inputs['Surface'])
    for key in ('skin', 'hair'):
        if key in mat:
            del mat[key]
    if kind == SKIN:
        mat['skin'] = True
    if kind == HAIR:
        mat['hair'] = True
    return mat


def build_rig(name):
    """The game's skeleton exactly as the soft dwarves had it, taken from the body file in the repo
    (or from the copy kept in this .blend once the new bodies have replaced that file)."""
    old = bpy.data.objects.get(name)
    if old:
        bpy.data.objects.remove(old, do_unlink=True)
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=os.path.join(REPO, 'assets', 'characters', 'knight.glb'))
    new = [o for o in bpy.data.objects if o not in before]
    rig = [o for o in new if o.type == 'ARMATURE'][0]
    for o in new:
        if o is not rig:
            bpy.data.objects.remove(o, do_unlink=True)
    rig.animation_data_clear()
    for key in list(rig.keys()):
        del rig[key]
    rig.name = rig.data.name = name
    for pb in rig.pose.bones:
        pb.rotation_mode = 'QUATERNION'
    return rig


def clear(B):
    for o in list(bpy.data.objects):
        if o.name.startswith(B['id']) or o.name == 'Rig_' + B['id']:
            bpy.data.objects.remove(o, do_unlink=True)
    old = bpy.data.collections.get('Dwarf_' + B['id'])
    if old:
        bpy.data.collections.remove(old)


def build(B, x=0.0):
    clear(B)
    col = bpy.data.collections.new('Dwarf_' + B['id'])
    bpy.context.scene.collection.children.link(col)
    rig = build_rig('Rig_' + B['id'])
    for c in list(rig.users_collection):
        c.objects.unlink(rig)
    col.objects.link(rig)
    mats = [material(B['id'] + '_cloth', CLOTH), material(B['id'] + '_skin', SKIN), material(B['id'] + '_hair', HAIR)]
    S = Sculpt(B['id'])
    chest = body_pieces(S, B)
    face = head_pieces(S, B)
    body = S.finish(col, mats, rig)
    woman = B['id'] == 'dwarf2'
    hair = woman_hair(B, rig, col, mats, chest) if woman else man_hair(B, rig, col, mats)
    beard = {} if woman else beards(B, rig, col, mats, face, chest)
    rig.location.x = x
    tris = {o.name: sum(len(p.vertices) - 2 for p in o.data.polygons) for o in [body, hair, *beard.values()]}
    return dict(B=B, rig=rig, body=body, hair=hair, beards=beard, tris=tris)


def show_beard(made, style):
    for name, ob in made['beards'].items():
        ob.hide_render = ob.hide_viewport = name != style


def relax_arms(rig, degrees=64):
    """Let the arms hang (the skeleton rests in a T), for pictures."""
    bpy.context.view_layer.objects.active = rig
    bpy.ops.object.mode_set(mode='POSE')
    for side, sign in (('l', 1), ('r', -1)):
        pb = rig.pose.bones['upperarm.' + side]
        pb.matrix_basis.identity()
        bpy.context.view_layer.update()
        h = pb.head.copy()
        pb.matrix = (Matrix.Translation(h) @ Matrix.Rotation(math.radians(degrees) * sign, 4, 'Y')
                     @ Matrix.Translation(-h)) @ pb.matrix
    bpy.ops.object.mode_set(mode='OBJECT')
    bpy.context.view_layer.update()


def rest(rig):
    for pb in rig.pose.bones:
        pb.matrix_basis.identity()
    bpy.context.view_layer.update()


def render_views(out_dir, tag, views=('front', 'three', 'side', 'back'), size=(640, 800), target=(0, 0, .68),
                 dist=4.4, lens=85):
    """Preview pictures (soft light, plain grey) to out_dir/<tag>_<view>.png."""
    scene = bpy.context.scene
    engines = [e.identifier for e in bpy.types.RenderSettings.bl_rna.properties['engine'].enum_items]
    scene.render.engine = next(e for e in engines if e.startswith('BLENDER_EEVEE'))
    scene.render.resolution_x, scene.render.resolution_y = size
    scene.render.image_settings.file_format = 'PNG'
    scene.view_settings.view_transform = 'Standard'
    world = scene.world or bpy.data.worlds.new('PreviewWorld')
    scene.world = world
    world.use_nodes = True
    bg = world.node_tree.nodes.get('Background')
    bg.inputs['Color'].default_value = (.55, .6, .66, 1)
    bg.inputs['Strength'].default_value = .9
    cam = bpy.data.objects.get('PreviewCam')
    if cam is None:
        cam = bpy.data.objects.new('PreviewCam', bpy.data.cameras.new('PreviewCam'))
        scene.collection.objects.link(cam)
    cam.data.lens = lens
    scene.camera = cam
    sun = bpy.data.objects.get('PreviewSun')
    if sun is None:
        sun = bpy.data.objects.new('PreviewSun', bpy.data.lights.new('PreviewSun', 'SUN'))
        scene.collection.objects.link(sun)
    sun.data.energy = 3.0
    sun.rotation_euler = Euler((math.radians(52), 0, math.radians(-32)))
    dirs = {'front': (0, -1, .05), 'three': (.6, -.8, .15), 'side': (1, 0, .05), 'back': (0, 1, .1),
            'rear': (-.6, .8, .2)}
    paths = []
    for v in views:
        loc = Vector(target) + Vector(dirs[v]).normalized() * dist
        cam.location = loc
        cam.rotation_euler = (Vector(target) - loc).to_track_quat('-Z', 'Y').to_euler()
        path = os.path.join(out_dir, '%s_%s.png' % (tag, v))
        scene.render.filepath = path
        bpy.ops.render.render(write_still=True)
        paths.append(path)
    return paths


def export_body(made, tmp_dir):
    """Write the body, hair, beards and skeleton to assets/characters/<game_id>.glb, at rest. The
    skeleton goes out under the game's name for it, marked softDwarf, so the game plays the soft
    dwarves' moves on it (assets/animations/soft-dwarf.glb)."""
    import subprocess
    rig, B = made['rig'], made['B']
    rest(rig)
    rig.location.x = 0
    rig['softDwarf'] = True
    meshes = [made['body'], made['hair'], *made['beards'].values()]
    for scene in bpy.data.scenes:
        for layer in scene.view_layers:
            for o in layer.objects:
                o.select_set(False, view_layer=layer)
    for o in [rig, *meshes]:
        o.hide_set(False)
        o.hide_viewport = False
        o.hide_render = False
        o.select_set(True)
    bpy.context.view_layer.objects.active = rig
    os.makedirs(tmp_dir, exist_ok=True)
    raw = os.path.join(tmp_dir, B['game_id'] + '.glb')
    old_name = rig.name
    rig.name = SKELETON
    try:
        bpy.ops.export_scene.gltf(
            filepath=raw, export_format='GLB', use_selection=True, use_active_scene=True, export_yup=True,
            export_apply=False, export_skins=True, export_animations=False,
            export_vertex_color='MATERIAL', export_all_vertex_colors=False, export_def_bones=False,
            export_materials='EXPORT', export_extras=True)
    finally:
        rig.name = old_name
    out = os.path.join(REPO, 'assets', 'characters', B['game_id'] + '.glb')
    subprocess.run(['node', os.path.join(REPO, 'tools', 'import-model.mjs'), raw, out, '--quantize'],
                   cwd=REPO, check=True, shell=os.name == 'nt')
    return made['tris']
